(window.V2_TALK=window.V2_TALK||{})["sens"]={"sens/cantine":[{"id":"V_musee_cantine_01","title":"Le pique-nique du musée","premise":"On a class field trip, Mrs. Petit, Léa and Inès eat lunch in the museum's lunchroom.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Les enfants, on mange vite : à une heure, l'atelier ludique commence.","en":"Kids, let's eat quickly: at one o'clock, the hands-on game workshop starts.","spans":[[52,59,"fr_ludique_adj"]]},{"speaker":"Léa","fr":"Encore des jeux ? Finalement, « musée » n'est pas synonyme d'« ennui » !","en":"More games? So \"museum\" doesn't mean \"boring\" after all!","spans":[[50,58,"fr_synonyme_adj"]]},{"speaker":"Inès","fr":"Madame, l'eau du robinet a un goût bizarre.","en":"Ma'am, the tap water tastes weird.","spans":[]},{"speaker":"Mme Petit","fr":"Elle est très calcaire, ici. Prends plutôt une bouteille.","en":"The water is very hard here. Take a bottle instead.","spans":[[14,22,"fr_calcaire_adj"]]},{"speaker":"Inès","fr":"Léa, pourquoi tu caches ton dessert derrière ton dos ?","en":"Léa, why are you hiding your dessert behind your back?","spans":[]},{"speaker":"Léa","fr":"C'est pour mon frère… Ne le dis à personne !","en":"It's for my brother… Don't tell anyone!","spans":[]},{"speaker":"Mme Petit","fr":"Léa est pudique : elle n'aime pas qu'on voie ses gentillesses.","en":"Léa is shy about it: she doesn't like people to see her kind deeds.","spans":[[8,15,"fr_pudique_adj"]]},{"speaker":"Inès","fr":"Oh ! Une maquette du Capitole de Washington ! Quelle joie indicible !","en":"Oh! A model of the Capitol in Washington! What indescribable joy!","spans":[[58,67,"fr_indicible_adj"]]},{"speaker":"Mme Petit","fr":"Moins fort, Inès ! Avec tout ce bruit, j'ai un mal de tête lancinant.","en":"Not so loud, Inès! With all this noise, I have a throbbing headache.","spans":[[59,68,"fr_lancinant_adj"]]}]}],"sens/emotions":[{"id":"V_musee_emotions_01","title":"Les larmes de joie","premise":"After a little show on the museum stage, the children talk about their feelings.","cefr":"C2","lines":[{"speaker":"Léa","fr":"Maman, Inès pleure !","en":"Mom, Inès is crying!","spans":[]},{"speaker":"Inès","fr":"Mais non, je suis émue ! Le petit spectacle était trop beau.","en":"No, I'm just moved! The little show was so beautiful.","spans":[[18,22,"fr_emu_adj"]]},{"speaker":"Maman","fr":"Inès est très sensible. C'est une qualité.","en":"Inès is very sensitive. That's a good quality.","spans":[[14,22,"fr_sensible_adj"]]},{"speaker":"Léa","fr":"Moi aussi, je suis émotive. J'ai pleuré au film des pingouins.","en":"I'm emotional too. I cried at the penguin movie.","spans":[[19,26,"fr_emotif_adj"]]},{"speaker":"Tom","fr":"Le garçon qui grimpe au mur d'escalade jusqu'en haut est hardi !","en":"The boy climbing all the way to the top of the climbing wall is bold!","spans":[[57,62,"fr_hardi_adj"]]},{"speaker":"Maman","fr":"Et le petit qui crie parce qu'il veut une glace… il est un peu capricieux.","en":"And the little one screaming because he wants ice cream… he's a bit spoiled.","spans":[[63,73,"fr_capricieux_adj"]]},{"speaker":"Léa","fr":"Il est pénible, oui !","en":"He's a pain, yes!","spans":[[7,14,"fr_penible_adj"]]},{"speaker":"Maman","fr":"Ne sois pas hautaine, Léa. Tu faisais pareil à son âge.","en":"Don't be so high and mighty, Léa. You did the same at his age.","spans":[[12,20,"fr_hautain_adj"]]},{"speaker":"Tom","fr":"La comédienne avait un visage très expressif. Elle a un talent enviable.","en":"The actress had a very expressive face. She has an enviable talent.","spans":[[35,44,"fr_expressif_adj"],[63,71,"fr_enviable_adj"]]}]}],"sens/saveurs":[{"id":"V_musee_saveurs_01","title":"L'atelier des saveurs","premise":"Mrs. Roux runs a tasting workshop in the museum kitchen.","cefr":"C1","lines":[{"speaker":"Mme Roux","fr":"Bienvenue à l'atelier des saveurs ! Aujourd'hui, c'est un goûter spécial.","en":"Welcome to the taste workshop! Today it's a special snack.","spans":[[65,72,"fr_special_adj"]]},{"speaker":"Tom","fr":"Je peux goûter le chocolat chaud ?","en":"Can I taste the hot chocolate?","spans":[]},{"speaker":"Mme Roux","fr":"Attention, il est brûlant ! Il est préférable d'attendre une minute.","en":"Careful, it's boiling hot! It's better to wait a minute.","spans":[[18,25,"fr_brulant_adj"],[35,45,"fr_preferable_adj"]]},{"speaker":"Léa","fr":"Moi, je veux la tarte aux fraises. C'est mon dessert favori.","en":"I want the strawberry tart. It's my favorite dessert.","spans":[[53,59,"fr_favori_adj"]]},{"speaker":"Mme Roux","fr":"Tu n'es allergique à rien ?","en":"You're not allergic to anything?","spans":[[8,18,"fr_allergique_adj"]]},{"speaker":"Léa","fr":"Non, juste aux chats !","en":"No, only to cats!","spans":[]},{"speaker":"Mme Roux","fr":"Et pour le bébé, voici une planche avec des boutons et des couleurs : c'est une bonne stimulation pour les sens.","en":"And for the baby, here's a board with buttons and colors: it's good stimulation for the senses.","spans":[[86,97,"fr_stimulation_noun"]]},{"speaker":"Mme Roux","fr":"Bon, qui est désireux d'apprendre la recette du cookie triple chocolat ?","en":"Now, who's eager to learn the recipe for the triple chocolate cookie?","spans":[[13,21,"fr_desireux_adj"],[55,61,"fr_triple_adj"]]},{"speaker":"Tom","fr":"Moi ! C'est vraiment agréable, ici.","en":"Me! It's really nice here.","spans":[[21,29,"fr_agreable_adj"]]}]}],"sens/caracteres":[{"id":"V_musee_caracteres_01","title":"Les portraits sévères","premise":"Mom and Léa stroll through the gallery of character portraits.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Maman, ce directeur sur le tableau a l'air très sévère.","en":"Mom, the principal in that painting looks very strict.","spans":[[48,54,"fr_severe_adj"]]},{"speaker":"Maman","fr":"Oui, il croise les bras. On dirait qu'il va te donner une punition !","en":"Yes, his arms are crossed. He looks like he's about to give you detention!","spans":[]},{"speaker":"Léa","fr":"Et la dame à côté, avec son grand chapeau et ses bijoux ?","en":"And the lady next to him, with her big hat and jewelry?","spans":[]},{"speaker":"Maman","fr":"Elle allait à toutes les soirées mondaines de Paris.","en":"She went to every fancy society party in Paris.","spans":[[33,42,"fr_mondain_adj"]]},{"speaker":"Léa","fr":"Son chapeau est grotesque : il y a un oiseau entier dessus !","en":"Her hat is ridiculous: there's a whole bird on it!","spans":[[16,25,"fr_grotesque_adj"]]},{"speaker":"Maman","fr":"C'était la mode ! Et le guide dit que son mari était très regardant : il comptait chaque centime.","en":"It was the fashion! And the guide says her husband was very tight with money: he counted every penny.","spans":[[58,67,"fr_regardant_adj"]]},{"speaker":"Léa","fr":"Et le vieux capitaine, là ? Il a la peau toute rouge.","en":"And the old captain there? His skin is all red.","spans":[]},{"speaker":"Maman","fr":"En mer, le soleil est implacable. Et le peintre a été impitoyable : il a peint chaque ride.","en":"At sea, the sun is relentless. And the painter was merciless: he painted every wrinkle.","spans":[[22,32,"fr_implacable_adj"],[54,65,"fr_impitoyable_adj"]]},{"speaker":"Léa","fr":"Mais ce portrait de chien, c'est un véritable chef-d'œuvre !","en":"But this portrait of a dog is a real masterpiece!","spans":[[36,45,"fr_veritable_adj"]]}]}],"sens/couleurs":[{"id":"V_musee_couleurs_01","title":"Le caméléon et le faon","premise":"Léa and Dad visit the cabinet of colors, where a painter is at work.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Papa, le peintre utilise un marron très foncé pour le faon.","en":"Dad, the painter is using a very dark brown for the fawn.","spans":[[40,45,"fr_fonce_adj"]]},{"speaker":"Papa","fr":"Et regarde le caméléon : sa couleur est changeante. Il devient vert, puis jaune.","en":"And look at the chameleon: its color keeps changing. It turns green, then yellow.","spans":[[40,50,"fr_changeant_adj"]]},{"speaker":"Léa","fr":"Mme Petit dit que le bleu et l'orange sont des couleurs complémentaires.","en":"Mrs. Petit says blue and orange are complementary colors.","spans":[[56,71,"fr_complementaire_adj"]]},{"speaker":"Papa","fr":"C'est vrai. Ensemble, elles sont éclatantes.","en":"That's right. Together, they're dazzling.","spans":[[33,43,"fr_eclatant_adj"]]},{"speaker":"Léa","fr":"Cette robe sur le tableau est ravissante ! On dirait une fête fastueuse chez un roi.","en":"That dress in the painting is lovely! It looks like a lavish party at a king's palace.","spans":[[30,40,"fr_ravissant_adj"],[62,71,"fr_fastueux_adj"]]},{"speaker":"Papa","fr":"Attention, ne touche pas ! Ces vieilles peintures sont précieuses.","en":"Careful, don't touch! These old paintings are precious.","spans":[[55,65,"fr_precieux_adj"]]},{"speaker":"Léa","fr":"Aïe ! Je me suis griffée sur le cadre… Mais c'est superficiel, c'est rien.","en":"Ouch! I scratched myself on the frame… But it's just a surface scratch, it's nothing.","spans":[[50,61,"fr_superficiel_adj"]]},{"speaker":"Papa","fr":"Ouf, une douleur momentanée. Et après, on fait quoi ?","en":"Phew, it'll only hurt for a moment. So what shall we do next?","spans":[[17,27,"fr_momentane_adj"]]},{"speaker":"Léa","fr":"J'ai une vague idée… une glace ?","en":"I have a vague idea… ice cream?","spans":[[9,14,"fr_vague_adj"]]}]}],"sens/fete":[{"id":"V_musee_fete_01","title":"La fête au musée","premise":"Tom, Léa and Mom enjoy a lively party in the museum's party room.","cefr":"C2","lines":[{"speaker":"Tom","fr":"Cette salle des fêtes est trop cool !","en":"This party room is so cool!","spans":[[31,35,"fr_cool_adj"]]},{"speaker":"Maman","fr":"L'ambiance est très festive, c'est vrai. Mais doucement, Tom !","en":"It's a really festive mood, that's true. But take it easy, Tom!","spans":[[20,27,"fr_festif_adj"]]},{"speaker":"Léa","fr":"Le garçon au skate est turbulent : il a fait tomber les guirlandes.","en":"The boy on the skateboard is rowdy: he knocked down the streamers.","spans":[[23,32,"fr_turbulent_adj"]]},{"speaker":"Maman","fr":"Avec tous ces enfants, c'est un peu chaotique…","en":"With all these kids, it's a little chaotic…","spans":[[36,45,"fr_chaotique_adj"]]},{"speaker":"Tom","fr":"Mais le spectacle de magie était sensationnel !","en":"But the magic show was sensational!","spans":[[33,45,"fr_sensationnel_adj"]]},{"speaker":"Léa","fr":"Regarde, Papi danse aussi ! Il est encore très actif.","en":"Look, Grandpa's dancing too! He's still very active.","spans":[[47,52,"fr_actif_adj"]]},{"speaker":"Maman","fr":"Et très décontracté, avec sa chemise à fleurs.","en":"And very relaxed, in his flowered shirt.","spans":[[8,19,"fr_decontracte_adj"]]},{"speaker":"Tom","fr":"Mon petit discours pour Léa est un peu brouillon. Je l'ai écrit en deux minutes.","en":"My little speech for Léa is a bit messy. I wrote it in two minutes.","spans":[[39,48,"fr_brouillon_adj"]]},{"speaker":"Léa","fr":"Pas grave, je l'aime quand même !","en":"No big deal, I love it anyway!","spans":[]}]}],"sens/voix":[{"id":"V_musee_voix_01","title":"L'enregistrement de la chorale","premise":"Mrs. Petit records the children's choir in the cabinet of voices.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Les enfants, aujourd'hui on enregistre la chorale pour le service audiovisuel du musée.","en":"Kids, today we're recording the choir for the museum's audiovisual department.","spans":[[66,77,"fr_audiovisuel_adj"]]},{"speaker":"Tom","fr":"Madame, la porte est grinçante ! On l'entend sur l'enregistrement.","en":"Ma'am, the door is squeaky! You can hear it on the recording.","spans":[[21,30,"fr_grincant_adj"]]},{"speaker":"Mme Petit","fr":"Je vais la fermer doucement. Léa, ta voix est très aiguë : chante un peu plus bas.","en":"I'll close it gently. Léa, your voice is very high: sing a little lower.","spans":[[51,56,"fr_aigu_adj"]]},{"speaker":"Léa","fr":"D'accord. Mais Inès a la voix tremblante, elle a peur du micro.","en":"OK. But Inès's voice is shaky, she's scared of the mic.","spans":[[30,40,"fr_tremblant_adj"]]},{"speaker":"Inès","fr":"Un peu… Et le pull rose criard de Tom me déconcentre !","en":"A little… And Tom's loud pink sweater is distracting me!","spans":[[24,30,"fr_criard_adj"]]},{"speaker":"Mme Petit","fr":"Bon, on recommence ? Tout le monde lève la main… C'est unanime !","en":"OK, shall we start again? Everyone's raising their hand… It's unanimous!","spans":[[55,62,"fr_unanime_adj"]]},{"speaker":"Tom","fr":"Cette fois, c'était harmonieux, non ?","en":"This time it was harmonious, wasn't it?","spans":[[20,30,"fr_harmonieux_adj"]]},{"speaker":"Mme Petit","fr":"Parfait. Et merci, Tom : tu as été moins volubile entre les chansons !","en":"Perfect. And thank you, Tom: you were less chatty between the songs!","spans":[[41,49,"fr_volubile_adj"]]}]}],"sens/optique":[{"id":"V_musee_optique_01","title":"Le brouillard de la vue","premise":"Mrs. Petit's class explores the cabinet of sight, with its fog, mirrors and a silver moon.","cefr":"C1","lines":[{"speaker":"Mme Petit","fr":"Tom, sois attentif : dans cette salle, on joue avec la perception.","en":"Tom, pay attention: in this room, we play with perception.","spans":[[10,18,"fr_attentif_adj"],[55,65,"fr_perception_noun"]]},{"speaker":"Tom","fr":"Je vois une silhouette derrière la vitre ! C'est un fantôme ?","en":"I can see a silhouette behind the glass! Is it a ghost?","spans":[[12,22,"fr_silhouette_noun"]]},{"speaker":"Mme Petit","fr":"Non, c'est un mannequin. La vitre est floue exprès.","en":"No, it's a mannequin. The glass is blurry on purpose.","spans":[[38,43,"fr_flou_adj"]]},{"speaker":"Léa","fr":"Et avec ce brouillard, la visibilité est nulle !","en":"And with this fog, there's zero visibility!","spans":[[26,36,"fr_visibilite_noun"]]},{"speaker":"Mme Petit","fr":"Regardez la lune argentée au fond. Avec l'éloignement, elle paraît toute petite.","en":"Look at the silver moon at the back. With the distance, it looks tiny.","spans":[[17,25,"fr_argente_adj"],[42,53,"fr_eloignement_noun"]]},{"speaker":"Inès","fr":"Elle a une aura, comme une lumière tout autour.","en":"It has an aura, like a light all around it.","spans":[[11,15,"fr_aura_noun"]]},{"speaker":"Mme Petit","fr":"Bravo, c'est un détail subtil. Les peintres adorent cet effet.","en":"Well done, that's a subtle detail. Painters love that effect.","spans":[[23,29,"fr_subtil_adj"]]},{"speaker":"Tom","fr":"Madame, mes lunettes sont floues aussi !","en":"Ma'am, my glasses are blurry too!","spans":[[26,32,"fr_flou_adj"]]},{"speaker":"Mme Petit","fr":"Ça, Tom, c'est juste de la buée. Essuie-les !","en":"That, Tom, is just fog on your lenses. Wipe them!","spans":[]}]}],"sens/toucher":[{"id":"V_musee_toucher_01","title":"Les boîtes mystère","premise":"With their eyes closed, the children guess what is hidden in the boxes of the cabinet of touch.","cefr":"B2","lines":[{"speaker":"Mme Petit","fr":"Dans le cabinet du toucher, on ferme les yeux et on met la main dans la boîte.","en":"In the cabinet of touch, you close your eyes and put your hand in the box.","spans":[[19,26,"fr_toucher_noun"]]},{"speaker":"Léa","fr":"Brr ! C'est glacé ! Quelle drôle de sensation !","en":"Brr! It's ice-cold! What a strange feeling!","spans":[[12,17,"fr_glace_adj"],[36,45,"fr_sensation_noun"]]},{"speaker":"Mme Petit","fr":"C'est un glaçon. Inès, à toi.","en":"It's an ice cube. Inès, your turn.","spans":[]},{"speaker":"Inès","fr":"C'est mou… et collant ! Beurk, de la pâte à modeler ?","en":"It's soft… and sticky! Yuck, modeling clay?","spans":[[6,9,"fr_mou_adj"],[14,21,"fr_collant_adj"]]},{"speaker":"Tom","fr":"Le mien est pointu ! Un hérisson ?","en":"Mine is pointy! A hedgehog?","spans":[[12,18,"fr_pointu_adj"]]},{"speaker":"Mme Petit","fr":"Non, une pomme de pin. Et l'autre boîte ?","en":"No, a pine cone. And the other box?","spans":[]},{"speaker":"Tom","fr":"Glissant… un savon ! Et celui-ci est rude, comme la barbe de Papi.","en":"Slippery… a bar of soap! And this one is rough, like Grandpa's beard.","spans":[[0,8,"fr_glissant_adj"],[37,41,"fr_rude_adj"]]},{"speaker":"Mme Petit","fr":"Le toucher demande de la sensibilité. Que dit votre instinct pour la dernière boîte ?","en":"Touch takes sensitivity. What does your instinct say about the last box?","spans":[[3,10,"fr_toucher_noun"],[25,36,"fr_sensibilite_noun"],[52,60,"fr_instinct_noun"]]},{"speaker":"Léa","fr":"Rien… ça ne pèse rien du tout ! Une plume ?","en":"Nothing… it weighs nothing at all! A feather?","spans":[]},{"speaker":"Mme Petit","fr":"Oui ! Quelle légèreté !","en":"Yes! How light it is!","spans":[[13,21,"fr_legerete_noun"]]}]}],"sens/parfums":[{"id":"V_musee_parfums_01","title":"Le nez de Papi","premise":"Grandpa Henri tests the children's sense of smell in the cabinet of scents.","cefr":"C1","lines":[{"speaker":"Papi Henri","fr":"Ici, c'est le cabinet des parfums. Il faut un bon odorat !","en":"This is the cabinet of scents. You need a good sense of smell!","spans":[[50,56,"fr_odorat_noun"]]},{"speaker":"Léa","fr":"Ce flacon sent la vanille. Quelle fragrance !","en":"This bottle smells of vanilla. What a fragrance!","spans":[[34,43,"fr_fragrance_noun"]]},{"speaker":"Papi Henri","fr":"Et celui-ci ? De la mangue et de la noix de coco… très exotique.","en":"And this one? Mango and coconut… very exotic.","spans":[[55,63,"fr_exotique_adj"]]},{"speaker":"Tom","fr":"Beurk ! Celui-là sent le vieux fromage. C'est désagréable !","en":"Yuck! That one smells like old cheese. It's unpleasant!","spans":[[46,57,"fr_desagreable_adj"]]},{"speaker":"Léa","fr":"Regarde Tom : il fait une grimace de dégoût !","en":"Look at Tom: he's making a face of disgust!","spans":[[37,43,"fr_degout_noun"]]},{"speaker":"Papi Henri","fr":"Ha ha ! Celui-ci est amer, comme le café noir. Et celui-là est suave, comme une rose.","en":"Ha ha! This one is bitter, like black coffee. And that one is smooth and sweet, like a rose.","spans":[[21,25,"fr_amer_adj"],[63,68,"fr_suave_adj"]]},{"speaker":"Tom","fr":"Le café, c'est amer, mais les croissants sont savoureux !","en":"Coffee is bitter, but croissants are delicious!","spans":[[15,19,"fr_amer_adj"],[46,55,"fr_savoureux_adj"]]},{"speaker":"Papi Henri","fr":"Toujours gourmand ! Sens plutôt l'effluve qui vient de la fenêtre…","en":"Always hungry! Smell the waft coming through the window instead…","spans":[[34,41,"fr_effluve_noun"]]},{"speaker":"Léa","fr":"La boulangerie ! Voilà une subtilité que Tom comprend !","en":"The bakery! Now that's a subtlety Tom understands!","spans":[[27,36,"fr_subtilite_noun"]]}]}],"sens/classe":[{"id":"V_musee_classe_01","title":"Le jeu des sons","premise":"Mrs. Petit runs a learning game in the museum classroom.","cefr":"C2","lines":[{"speaker":"Mme Petit","fr":"Tout le monde est assis ? Bien. Cet atelier est didactique : on apprend en jouant.","en":"Is everyone seated? Good. This workshop is educational: we learn by playing.","spans":[[18,23,"fr_assis_adj"],[48,58,"fr_didactique_adj"]]},{"speaker":"Tom","fr":"Madame, le jeu de l'alphabet phonétique est ardu !","en":"Ma'am, the phonetic alphabet game is hard!","spans":[[29,39,"fr_phonetique_adj"],[44,48,"fr_ardu_adj"]]},{"speaker":"Mme Petit","fr":"Un peu, mais tu progresses. Léa, ton histoire est cohérente ?","en":"A little, but you're getting better. Léa, does your story hang together?","spans":[[50,59,"fr_coherent_adj"]]},{"speaker":"Léa","fr":"Oui : le début, le milieu et la fin vont ensemble !","en":"Yes: the beginning, the middle and the end all fit!","spans":[]},{"speaker":"Inès","fr":"Et moi, j'ai gagné la partie. C'est incontestable !","en":"And I won the game. No one can argue with that!","spans":[[36,49,"fr_incontestable_adj"]]},{"speaker":"Mme Petit","fr":"Bravo, Inès. Tom, tu es conscient de l'heure ? Il reste cinq minutes.","en":"Well done, Inès. Tom, are you aware of the time? There are five minutes left.","spans":[[24,33,"fr_conscient_adj"]]},{"speaker":"Tom","fr":"Déjà ? On arrive à l'étape terminale du jeu !","en":"Already? We're getting to the final stage of the game!","spans":[[27,36,"fr_terminal_adj"]]},{"speaker":"Mme Petit","fr":"Alors on range. Et sois civil : laisse passer les filles devant le placard.","en":"Then let's tidy up. And be polite: let the girls go first at the cupboard.","spans":[[24,29,"fr_civil_adj"]]}]}],"sens/coulisse":[{"id":"C_ST_perception_seg001","title":"La surprise à la gare","premise":"A woman unexpectedly spots an old friend at the station.","cefr":"A1","lines":[{"speaker":"Laure","fr":"Fanny ? Je t'ai aperçue de loin !","en":"Fanny? I spotted you from a distance!","spans":[]},{"speaker":"Fanny","fr":"Laure ! Quelle surprise ! Je ne t'ai pas vue depuis dix ans.","en":"Laure! What a surprise! I haven't seen you for ten years.","spans":[]},{"speaker":"Laure","fr":"Tu m'as surprise ! J'ai entendu ta voix et j'ai reconnu ton rire.","en":"You surprised me! I heard your voice and recognized your laugh.","spans":[]},{"speaker":"Fanny","fr":"Ça m'étonne que tu te souviennes !","en":"I'm surprised you remember!","spans":[[5,11,"fr_etonner_verb"]]},{"speaker":"Laure","fr":"Bien sûr ! Tu prends quel train ?","en":"Of course! Which train are you taking?","spans":[]},{"speaker":"Fanny","fr":"Celui de quinze heures, pour Lyon.","en":"The three o'clock, to Lyon.","spans":[]},{"speaker":"Laure","fr":"Note mon numéro, on se revoit vite.","en":"Write down my number, let's meet up soon.","spans":[[0,4,"fr_noter_verb"]]},{"speaker":"Fanny","fr":"Avec plaisir !","en":"With pleasure!","spans":[]}]},{"id":"C_ST_perception_seg002","title":"Le vieux quartier","premise":"A man returns to his childhood neighborhood with his daughter.","cefr":"A1","lines":[{"speaker":"M. Moreau","fr":"Je revois la boulangerie de mon enfance !","en":"I can see my childhood bakery again!","spans":[]},{"speaker":"Julie","fr":"Tu la reconnais ?","en":"Do you recognize it?","spans":[[6,15,"fr_reconnaitre_verb"]]},{"speaker":"M. Moreau","fr":"Oui. Sens cette odeur de pain !","en":"Yes. Smell that bread!","spans":[]},{"speaker":"Julie","fr":"Mmm ! Regarde, il y a un vieux monsieur à la porte.","en":"Mmm! Look, there's an old man at the door.","spans":[[6,13,"fr_regarder_verb"]]},{"speaker":"M. Moreau","fr":"C'est le boulanger ! Écoute, il chante comme avant.","en":"It's the baker! Listen, he's singing like before.","spans":[]},{"speaker":"Julie","fr":"Je constate que tu es ému !","en":"I can see you're moved!","spans":[[3,11,"fr_constater_verb"]]},{"speaker":"M. Moreau","fr":"Un peu. Allez, on achète un croissant.","en":"A bit. Come on, let's buy a croissant.","spans":[]},{"speaker":"Julie","fr":"D'accord !","en":"OK!","spans":[]}]},{"id":"V_sens_coulisse_01","title":"Dans les coulisses","premise":"After the magic show, Tom, Léa and Mom step through the stage curtain into the wings.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Tu as vu le lapin dans le chapeau ?","en":"Did you see the rabbit in the hat?","spans":[[3,8,"fr_voir_verb"]]},{"speaker":"Tom","fr":"Oui ! Et le coffre m'a surpris : un petit loup a sauté dehors.","en":"Yes! And the chest surprised me: a little wolf jumped out.","spans":[[21,30,"fr_surprendre_verb"]]},{"speaker":"Maman","fr":"Le poney a l'air étonné devant toutes ces carottes.","en":"The pony looks astonished in front of all those carrots.","spans":[[17,23,"fr_etonner_verb"]]},{"speaker":"Léa","fr":"Regarde le garçon : il observe avec des jumelles.","en":"Look at the boy: he's watching through binoculars.","spans":[[0,7,"fr_regarder_verb"],[23,30,"fr_observer_verb"]]},{"speaker":"Tom","fr":"Je l'aperçois, oui. Et je reconnais l'oie : c'est la même que sur l'affiche.","en":"I catch sight of him, yes. And I recognize the goose: it's the same one as on the poster.","spans":[[5,13,"fr_apercevoir_verb"],[26,35,"fr_reconnaitre_verb"]]},{"speaker":"Maman","fr":"La fille note tout, et l'agent constate la même chose dans son carnet.","en":"The girl is taking notes, and the officer is recording the same thing in his notebook.","spans":[[9,13,"fr_noter_verb"],[31,39,"fr_constater_verb"]]},{"speaker":"Léa","fr":"Le hibou observe avec sa longue-vue. Et tu as remarqué le nez du chat ?","en":"The owl is observing with its telescope. And did you notice the cat's nose?","spans":[[9,16,"fr_observer_verb"],[43,54,"fr_remarquer_verb"]]}]}],"sens/ouie":[{"id":"C_ST_perception_seg003","title":"Le vernissage","premise":"An artist talks with a visitor at the opening of her exhibition.","cefr":"A2","lines":[{"speaker":"Margot","fr":"Vous exposez ici pour la première fois ?","en":"Is this your first time exhibiting here?","spans":[[5,12,"fr_exposer_verb"]]},{"speaker":"Mme Durand","fr":"Oui ! Je montre mes peintures de la mer.","en":"Yes! I'm showing my paintings of the sea.","spans":[[9,15,"fr_montrer_verb"]]},{"speaker":"Margot","fr":"On peut toucher ?","en":"Can we touch?","spans":[[8,15,"fr_toucher_verb"]]},{"speaker":"Mme Durand","fr":"Non, s'il vous plaît ! Mais regardez de près : un bateau apparaît dans la brume.","en":"No, please! But look closely: a boat appears in the mist.","spans":[[57,65,"fr_apparaitre_verb"]]},{"speaker":"Margot","fr":"Ah oui ! Il paraît que vous peignez sur la plage.","en":"Oh yes! Apparently you paint on the beach.","spans":[[12,18,"fr_paraitre_verb"]]},{"speaker":"Mme Durand","fr":"C'est vrai.","en":"That's true.","spans":[]},{"speaker":"Margot","fr":"Vous pouvez signer mon catalogue ?","en":"Could you sign my catalog?","spans":[]},{"speaker":"Mme Durand","fr":"Avec plaisir.","en":"With pleasure.","spans":[]}]},{"id":"V_sens_ouie_01","title":"On entend tout","premise":"Tom, Léa and Mom step through the teal door and notice everything in the cabinet.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Tu entends la souris sous la neige ? Le renard l'écoute.","en":"Do you hear the mouse under the snow? The fox is listening.","spans":[[3,10,"fr_entendre_verb"]]},{"speaker":"Tom","fr":"Et le chien sent les saucisses. Moi, je veux les toucher, mais non !","en":"And the dog smells the sausages. I want to touch them, but no!","spans":[[12,16,"fr_sentir_verb"],[49,56,"fr_toucher_verb"]]},{"speaker":"Maman","fr":"La fille montre ses médailles, et le peintre expose trois tableaux.","en":"The girl is showing her medals, and the painter is exhibiting three pictures.","spans":[[9,15,"fr_montrer_verb"],[45,51,"fr_exposer_verb"]]},{"speaker":"Tom","fr":"Un fantôme apparaît avec une lanterne. Et le perroquet paraît à la fenêtre.","en":"A ghost appears with a lantern. And the parrot appears at the window.","spans":[[11,19,"fr_apparaitre_verb"],[55,61,"fr_paraitre_verb"]]},{"speaker":"Léa","fr":"Ces deux amis se revoient. Le suricate surveille, et l'agent contrôle le billet.","en":"Those two friends are seeing each other again. The meerkat is watching, and the officer is checking the ticket.","spans":[[17,25,"fr_revoir_verb"],[39,48,"fr_surveiller_verb"],[61,69,"fr_controler_verb"]]}]}],"sens/couloir":[{"id":"V_sens_couloir_01","title":"Sept portes","premise":"Léa, Tom and Mom stand in the lantern hall and choose a door.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Sept portes, et des lanternes partout ! Laquelle on ouvre ?","en":"Seven doors, and lanterns everywhere! Which one do we open?","spans":[]},{"speaker":"Tom","fr":"La verte a un renard. La rouge a un grand chapeau.","en":"The green one has a fox. The red one has a big hat.","spans":[]},{"speaker":"Maman","fr":"La porte crème a une bougie, et la violette une plume.","en":"The cream door has a candle, and the purple one a feather.","spans":[]},{"speaker":"Léa","fr":"La bleue a une échelle. La brune, tout au bout, a une arche.","en":"The blue one has a ladder. The brown one, at the far end, has an arch.","spans":[]},{"speaker":"Tom","fr":"On commence par la bougie. Je veux voir ce qu'il y a derrière.","en":"Let's start with the candle. I want to see what's behind it.","spans":[]},{"speaker":"Maman","fr":"D'accord. Ensuite le chapeau, la plume, puis l'échelle.","en":"All right. Then the hat, the feather, then the ladder.","spans":[]}]}],"sens/couloir2":[{"id":"V_sens_couloir2_01","title":"Le second couloir","premise":"The family comes through the arch into the second hall and reads the doors.","cefr":"A2","lines":[{"speaker":"Tom","fr":"L'arche nous ramène au premier couloir. Et ici, cinq nouvelles portes.","en":"The arch takes us back to the first hall. And here, five new doors.","spans":[]},{"speaker":"Léa","fr":"La jaune a un cadre. La grise a une pelote de laine.","en":"The yellow one has a frame. The grey one has a ball of yarn.","spans":[]},{"speaker":"Papi Henri","fr":"Le ruban rouge, c'est pour la place. La loupe bleue, pour les traces.","en":"The red ribbon is for the square. The blue magnifying glass is for the clues.","spans":[]},{"speaker":"Tom","fr":"Et la porte orange a un pinceau. On y va en dernier ?","en":"And the orange door has a paintbrush. Shall we go there last?","spans":[]},{"speaker":"Léa","fr":"D'abord le cadre. Je veux voir le dessin.","en":"The frame first. I want to see the drawing.","spans":[]},{"speaker":"Papi Henri","fr":"Allez. On revient par l'arche quand vous aurez fait le tour.","en":"Go on. We'll come back through the arch when you've been all the way around.","spans":[]}]}],"sens/etat":[{"id":"C_ST_existence_seg002","title":"La nouvelle naissance","premise":"Two friends talk about a baby born in the family.","cefr":"A2","lines":[{"speaker":"Julie","fr":"Ma sœur a accouché ! Le bébé est né hier soir.","en":"My sister's had her baby! He was born last night.","spans":[[29,32,"fr_etre_verb"]]},{"speaker":"Marion","fr":"Félicitations ! Il est comment ?","en":"Congratulations! What's he like?","spans":[[19,22,"fr_etre_verb"]]},{"speaker":"Julie","fr":"Il semble très calme. Il dort tout le temps.","en":"He seems very calm. He sleeps all the time.","spans":[[3,9,"fr_sembler_verb"]]},{"speaker":"Marion","fr":"L'accouchement a duré longtemps ?","en":"Did the birth last a long time?","spans":[[15,21,"fr_durer_verb"]]},{"speaker":"Julie","fr":"Douze heures. Elle est fatiguée, mais heureuse.","en":"Twelve hours. She's tired, but happy.","spans":[[19,22,"fr_etre_verb"]]},{"speaker":"Marion","fr":"Tu vas la voir quand ?","en":"When are you going to see her?","spans":[]},{"speaker":"Julie","fr":"Ça dépend des visites à l'hôpital. Peut-être demain.","en":"It depends on the hospital visiting hours. Maybe tomorrow.","spans":[[3,9,"fr_dependre_verb"]]},{"speaker":"Marion","fr":"Apporte-lui une boîte qui contient des petits gâteaux !","en":"Take her a box with some little cakes in it!","spans":[]},{"speaker":"Julie","fr":"Bonne idée. Être tante, c'est génial !","en":"Good idea. Being an aunt is brilliant!","spans":[[12,16,"fr_etre_verb"],[26,29,"fr_etre_verb"]]}]},{"id":"V_sens_etat_01","title":"Comment c'est","premise":"In the room of how things are, Mom names what each figure is doing.","cefr":"A2","lines":[{"speaker":"Maman","fr":"Le renard est le spectacle, là, sous la lampe.","en":"The fox is the show, there, under the lamp.","spans":[[10,13,"fr_etre_verb"]]},{"speaker":"Léa","fr":"Et la licorne existe : elle sort du nuage !","en":"And the unicorn exists: it's stepping out of the cloud!","spans":[[14,20,"fr_exister_verb"]]},{"speaker":"Tom","fr":"Le chat semble un dragon, mais c'est seulement son ombre.","en":"The cat seems to be a dragon, but it's only its shadow.","spans":[[8,14,"fr_sembler_verb"],[33,36,"fr_etre_verb"]]},{"speaker":"Maman","fr":"La bougie dure encore. La tour de pierre perdure, et les noix de coco subsistent à côté.","en":"The candle is still lasting. The stone tower continues, and the coconuts remain beside it.","spans":[[10,14,"fr_durer_verb"],[41,48,"fr_perdurer_verb"],[70,80,"fr_subsister_verb"]]},{"speaker":"Léa","fr":"La médaille vaut plus que la petite couronne.","en":"The medal is worth more than the little crown.","spans":[[12,16,"fr_valoir_verb"]]},{"speaker":"Tom","fr":"Un parapluie suffit pour les enfants et les canards.","en":"One umbrella is enough for the children and the ducks.","spans":[[13,19,"fr_suffire_verb"]]},{"speaker":"Maman","fr":"Le singe dépend de sa liane. Et le goûter consiste en une tartine de confiture.","en":"The monkey depends on its vine. And the snack consists of bread and jam.","spans":[[9,15,"fr_dependre_verb"],[42,50,"fr_consister_verb"]]}]}],"sens/changement":[{"id":"V_sens_changement_01","title":"Tout change","premise":"Tom and Léa watch things change around the room.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Le lapin disparaît dans le chapeau, puis il revient !","en":"The rabbit disappears into the hat, then it comes back!","spans":[[9,18,"fr_disparaitre_verb"]]},{"speaker":"Tom","fr":"La petite voiture-biberon naît juste à côté.","en":"The little bottle-car is born right beside it.","spans":[[26,30,"fr_naitre_verb"]]},{"speaker":"Maman","fr":"Le hibou sépare les deux chatons, un sous chaque aile.","en":"The owl separates the two kittens, one under each wing.","spans":[[9,15,"fr_separer_verb"]]},{"speaker":"Léa","fr":"La vache survient et s'assoit sur la carte du monsieur.","en":"The cow turns up and sits on the man's map.","spans":[[9,17,"fr_survenir_verb"]]},{"speaker":"Tom","fr":"Les assiettes cassées résultent du chat noir.","en":"The broken plates result from the black cat.","spans":[[22,31,"fr_resulter_verb"]]},{"speaker":"Maman","fr":"Le chef unifie la souris, l'oiseau et la grenouille. Et les cailloux constituent un chat.","en":"The conductor unifies the mouse, the bird and the frog. And the pebbles make up a cat.","spans":[[8,14,"fr_unifier_verb"],[69,80,"fr_constituer_verb"]]},{"speaker":"Léa","fr":"Près de la fenêtre, le brouillard se dissipe. Le héron reste.","en":"By the window, the fog dissipates. The heron stays.","spans":[[37,44,"fr_dissiper_verb"]]}]},{"id":"C_ST_existence_seg006","title":"La vieille ferme","premise":"A historian explains the history of an old farmhouse to visitors.","cefr":"B2","lines":[{"speaker":"l'historienne","fr":"Cette ferme date du seizième siècle.","en":"This farm dates from the sixteenth century.","spans":[]},{"speaker":"un visiteur","fr":"C'est impressionnant. Qu'est-ce qui subsiste de l'époque ?","en":"It's impressive. What remains from that period?","spans":[]},{"speaker":"l'historienne","fr":"Les murs et la grande cheminée. Le reste résulte de travaux au dix-neuvième siècle.","en":"The walls and the big fireplace. The rest is the result of work in the nineteenth century.","spans":[[41,48,"fr_resulter_verb"]]},{"speaker":"un visiteur","fr":"Il y a eu un incendie ?","en":"Was there a fire?","spans":[]},{"speaker":"l'historienne","fr":"Oui, un incendie est survenu en 1820.","en":"Yes, a fire broke out in 1820.","spans":[[21,28,"fr_survenir_verb"]]},{"speaker":"un visiteur","fr":"Et ces bâtiments constituent le village d'origine ?","en":"And do these buildings make up the original village?","spans":[[17,28,"fr_constituer_verb"]]},{"speaker":"l'historienne","fr":"Exactement. Munissez-vous de vos lampes, on descend dans la cave !","en":"Exactly. Take your flashlights, we're going down to the cellar!","spans":[]},{"speaker":"un visiteur","fr":"D'accord !","en":"OK!","spans":[]}]}],"sens/effluves":[{"id":"V_sens_effluves_01","title":"Ça se répand","premise":"In the scent room, Léa and Tom follow what spreads.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Le putois se parfume à la lavande. Ça sent fort !","en":"The skunk perfumes itself with lavender. That smells strong!","spans":[[13,20,"fr_parfumer_verb"]]},{"speaker":"Tom","fr":"Le panda répand le miel par terre. Attention aux chaussures.","en":"The panda spreads the honey on the floor. Watch your shoes.","spans":[[9,15,"fr_repandre_verb"]]},{"speaker":"Maman","fr":"La petite tour diffuse un air, et les pigeons écoutent.","en":"The little tower broadcasts a tune, and the pigeons listen.","spans":[[15,22,"fr_diffuser_verb"]]},{"speaker":"Léa","fr":"L'éternuement disperse le pissenlit, et le vent éparpille les papiers.","en":"The sneeze scatters the dandelion, and the wind scatters the papers.","spans":[[14,22,"fr_disperser_verb"],[48,57,"fr_eparpiller_verb"]]},{"speaker":"Tom","fr":"Le garçon sue. Il a trop chaud.","en":"The boy is sweating. He's too hot.","spans":[[10,13,"fr_suer_verb"]]},{"speaker":"Maman","fr":"Les enfants entourent la fenêtre, et le paon exhibe toute sa queue.","en":"The children surround the window, and the peacock shows off its whole tail.","spans":[[12,21,"fr_entourer_verb"],[45,51,"fr_exhiber_verb"]]}]},{"id":"C_ST_perception_seg010","title":"La séance de sport","premise":"Two friends after a hot-yoga class.","cefr":"B2","lines":[{"speaker":"Léa","fr":"J'ai sué comme jamais !","en":"I sweated like never before!","spans":[[2,8,"fr_suer_verb"]]},{"speaker":"Sonia","fr":"Moi aussi ! La salle diffuse une odeur de lavande.","en":"Me too! The room gives off a lavender smell.","spans":[[21,28,"fr_diffuser_verb"]]},{"speaker":"Léa","fr":"Ils parfument la salle pour la détente.","en":"They scent the room for relaxation.","spans":[[4,13,"fr_parfumer_verb"]]},{"speaker":"Sonia","fr":"La rumeur se répand : le prof va partir.","en":"The rumor's spreading: the teacher is leaving.","spans":[[13,19,"fr_repandre_verb"]]},{"speaker":"Léa","fr":"Non !","en":"No!","spans":[]},{"speaker":"Sonia","fr":"Si. Je suis dépouillée de mon prof préféré !","en":"Yes. I'm being robbed of my favorite teacher!","spans":[]},{"speaker":"Léa","fr":"Ha ha ! Tu exagères.","en":"Ha ha! You're exaggerating.","spans":[]},{"speaker":"Sonia","fr":"Un peu.","en":"A bit.","spans":[]}]}],"sens/devoir":[{"id":"C_ST_existence_seg004","title":"Le bénévole","premise":"A woman thanks a volunteer who helps at the food bank.","cefr":"A2","lines":[{"speaker":"Mme Perrin","fr":"Antoine, merci pour ton aide. Tu mérites une médaille !","en":"Antoine, thank you for your help. You deserve a medal!","spans":[[33,40,"fr_meriter_verb"]]},{"speaker":"Antoine","fr":"C'est normal. Il faut agir quand on peut aider.","en":"It's nothing. You have to act when you can help.","spans":[[17,21,"fr_falloir_verb"],[22,26,"fr_agir_verb"],[36,40,"fr_pouvoir_verb"]]},{"speaker":"Mme Perrin","fr":"Tu pourrais revenir samedi ?","en":"Could you come back on Saturday?","spans":[[3,11,"fr_pouvoir_verb"]]},{"speaker":"Antoine","fr":"Oui, bien sûr. Ce travail me passionne.","en":"Yes, of course. I love this work.","spans":[[29,38,"fr_passionner_verb"]]},{"speaker":"Mme Perrin","fr":"Il faut être là à huit heures.","en":"You need to be here at eight.","spans":[[3,7,"fr_falloir_verb"]]},{"speaker":"Antoine","fr":"Pas de problème. Une heure de sommeil en moins, ça suffit !","en":"No problem. An hour's less sleep is fine!","spans":[]},{"speaker":"Mme Perrin","fr":"Ha ha ! Merci, tu es un ange.","en":"Ha ha! Thanks, you're an angel.","spans":[]},{"speaker":"Antoine","fr":"De rien !","en":"You're welcome!","spans":[]}]},{"id":"V_sens_devoir_01","title":"Il faut","premise":"Mom and the children sort out who must do what in the duty room.","cefr":"A2","lines":[{"speaker":"Léa","fr":"La fille agit tout de suite pour attraper le cerf-volant.","en":"The girl acts at once to catch the kite.","spans":[[9,13,"fr_agir_verb"]]},{"speaker":"Tom","fr":"L'homme maintient l'échelle. Sans lui, elle tombe.","en":"The man keeps the ladder steady. Without him, it falls.","spans":[[8,17,"fr_maintenir_verb"]]},{"speaker":"Maman","fr":"Le garçon à la cape verte peut porter la voiture jaune.","en":"The boy in the green cape can carry the yellow car.","spans":[[26,30,"fr_pouvoir_verb"]]},{"speaker":"Léa","fr":"Le petit exige le biscuit, les bras croisés. Et l'autre doit finir sa pile de feuilles.","en":"The little one demands the cookie, arms folded. And the other one has to finish his stack of papers.","spans":[[9,14,"fr_exiger_verb"],[56,60,"fr_devoir_verb"]]},{"speaker":"Tom","fr":"La tortue patiente près du panneau. Elle a le temps.","en":"The tortoise waits patiently by the sign. It has time.","spans":[[10,18,"fr_patienter_verb"]]},{"speaker":"Maman","fr":"La fourmi mérite sa médaille. Le cheval se passionne pour le papillon.","en":"The ant deserves its medal. The horse is fascinated by the butterfly.","spans":[[10,16,"fr_meriter_verb"],[43,52,"fr_passionner_verb"]]},{"speaker":"Léa","fr":"On recense les moutons : un, deux, trois. Et il faut suivre la carte, disent les trois agents.","en":"We count the sheep: one, two, three. And you have to follow the map, the three officers say.","spans":[[3,10,"fr_recenser_verb"],[48,52,"fr_falloir_verb"]]}]},{"id":"C_ST_existence_seg005","title":"Le contrat de location","premise":"A tenant reads a rental contract with the landlord.","cefr":"B2","lines":[{"speaker":"le propriétaire","fr":"Voici le contrat. Il comporte six pages.","en":"Here's the contract. It's six pages long.","spans":[]},{"speaker":"Laura","fr":"Le loyer inclut les charges ?","en":"Does the rent include service charges?","spans":[]},{"speaker":"le propriétaire","fr":"Oui, l'eau et le chauffage sont inclus.","en":"Yes, water and heating are included.","spans":[]},{"speaker":"Laura","fr":"Et en quoi consiste le dépôt de garantie ?","en":"And what does the deposit involve?","spans":[]},{"speaker":"le propriétaire","fr":"Un mois de loyer. Je dois aussi faire l'état des lieux avec vous.","en":"One month's rent. I also have to do the inventory with you.","spans":[[21,25,"fr_devoir_verb"]]},{"speaker":"Laura","fr":"Vous exigez un garant ?","en":"Do you require a guarantor?","spans":[[5,11,"fr_exiger_verb"]]},{"speaker":"le propriétaire","fr":"Oui, c'est obligatoire.","en":"Yes, it's compulsory.","spans":[]},{"speaker":"Laura","fr":"Et la mairie, elle recense les nouveaux habitants ?","en":"And does the town hall register new residents?","spans":[[19,26,"fr_recenser_verb"]]},{"speaker":"le propriétaire","fr":"Oui, inscrivez-vous là-bas pour voter.","en":"Yes, sign up there to vote.","spans":[]}]}],"sens/lien":[{"id":"V_sens_lien_01","title":"Dedans et ensemble","premise":"Papi Henri shows Léa and Tom what belongs, what contains, and what matches.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Le gant appartient au bonhomme de neige. Il est juste à côté.","en":"The mitten belongs to the snowman. It's right beside him.","spans":[[8,18,"fr_appartenir_verb"]]},{"speaker":"Tom","fr":"Le cornet contient une haute pile de boules. Le panier comporte un sandwich, une pomme et une bouteille.","en":"The cone contains a tall stack of scoops. The lunchbox includes a sandwich, an apple and a bottle.","spans":[[10,18,"fr_contenir_verb"],[55,63,"fr_comporter_verb"]]},{"speaker":"Papi Henri","fr":"Le grand sandwich inclut tout un pique-nique. Et la grange renferme les animaux.","en":"The giant sandwich includes a whole picnic. And the barn contains the animals.","spans":[[18,24,"fr_inclure_verb"],[59,67,"fr_renfermer_verb"]]},{"speaker":"Léa","fr":"La dame base son explication sur la boule bleue.","en":"The woman bases her explanation on the blue globe.","spans":[[8,12,"fr_baser_verb"]]},{"speaker":"Tom","fr":"On compare les deux familles. On les apparente : même sourire.","en":"We compare the two families. We link them as related: the same smile.","spans":[[3,10,"fr_comparer_verb"],[37,46,"fr_apparenter_verb"]]},{"speaker":"Papi Henri","fr":"Les deux garçons coïncident sur la même pièce. Et un œuf d'or n'équivaut pas à tous les blancs.","en":"The two boys coincide on the same coin. And one gold egg is not equivalent to all the white ones.","spans":[[17,27,"fr_coincider_verb"],[64,72,"fr_equivaloir_verb"]]}]}],"sens/garde":[{"id":"V_sens_garde_01","title":"On garde","premise":"Mom points out everyone who is keeping, tending or passing something on.","cefr":"B1","lines":[{"speaker":"Maman","fr":"Mamie préserve la confiture dans les pots.","en":"Grandma preserves the jam in the jars.","spans":[[6,14,"fr_preserver_verb"]]},{"speaker":"Tom","fr":"Le garçon entretient la grande horloge. Et le pic persiste : toc, toc, toc.","en":"The boy maintains the tall clock. And the woodpecker persists: knock, knock, knock.","spans":[[10,20,"fr_entretenir_verb"],[50,58,"fr_persister_verb"]]},{"speaker":"Léa","fr":"L'autre mamie perpétue la recette dans le grand livre.","en":"The other grandma keeps the recipe going in the big book.","spans":[[14,22,"fr_perpetuer_verb"]]},{"speaker":"Maman","fr":"La bibliothécaire détient une pile de livres pour le garçon.","en":"The librarian holds a stack of books for the boy.","spans":[[18,25,"fr_detenir_verb"]]},{"speaker":"Tom","fr":"Le soldat munit le cheval d'une gourde.","en":"The soldier equips the horse with a canteen.","spans":[[10,15,"fr_munir_verb"]]},{"speaker":"Léa","fr":"La fille confie un secret à l'escargot. Et le monsieur dédie une page de son livre.","en":"The girl confides a secret to the snail. And the man dedicates a page of his book.","spans":[[9,15,"fr_confier_verb"],[55,60,"fr_dedier_verb"]]}]},{"id":"C_ST_existence_seg010","title":"La coïncidence","premise":"Two old school friends meet by chance abroad.","cefr":"C1","lines":[{"speaker":"Nadia","fr":"Hugo ? C'est toi ? Quelle coïncidence !","en":"Hugo? Is that you? What a coincidence!","spans":[]},{"speaker":"Hugo","fr":"Nadia ! On se retrouve à Lisbonne, c'est fou !","en":"Nadia! Meeting in Lisbon, that's crazy!","spans":[]},{"speaker":"Nadia","fr":"Nos vacances coïncident ! Tu es là pour quoi ?","en":"Our vacations coincide! What are you here for?","spans":[]},{"speaker":"Hugo","fr":"Pour le travail. Je travaille pour une association qui aide à rapatrier les touristes en difficulté.","en":"For work. I work for an organization that helps repatriate tourists in trouble.","spans":[]},{"speaker":"Nadia","fr":"Intéressant ! Et ta passion pour la musique, elle persiste ?","en":"Interesting! And your passion for music, is it still going?","spans":[[50,58,"fr_persister_verb"]]},{"speaker":"Hugo","fr":"Oui, je joue encore. J'essaie de concilier travail et musique.","en":"Yes, I still play. I try to balance work and music.","spans":[]},{"speaker":"Nadia","fr":"Bravo. Il faut préserver ce qu'on aime.","en":"Well done. You have to hold on to what you love.","spans":[[15,24,"fr_preserver_verb"]]},{"speaker":"Hugo","fr":"Et toi, tu détiens toujours le record du lycée au 100 mètres ?","en":"And you, do you still hold the school record for the 100 meters?","spans":[[11,18,"fr_detenir_verb"]]},{"speaker":"Nadia","fr":"Ha ha ! Je crois !","en":"Ha ha! I think so!","spans":[]}]}],"sens/forme":[{"id":"V_sens_forme_01","title":"Ça prend forme","premise":"Léa and Tom walk through the room where things are packed, framed and fitted.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Elle tasse les vêtements dans la valise. Ça déborde un peu.","en":"She packs the clothes down into the suitcase. It overflows a little.","spans":[[5,10,"fr_tasser_verb"]]},{"speaker":"Tom","fr":"Les cubes emboîtent bien dans la caisse.","en":"The blocks fit together nicely in the box.","spans":[[10,19,"fr_emboiter_verb"]]},{"speaker":"Papi Henri","fr":"Le dessin représente sa famille. Et le photographe cadre la petite voiture bleue.","en":"The drawing represents his family. And the photographer frames the little blue car.","spans":[[10,20,"fr_representer_verb"],[51,56,"fr_cadrer_verb"]]},{"speaker":"Léa","fr":"Le peintre dépeint le coucher du soleil.","en":"The painter depicts the sunset.","spans":[[11,18,"fr_depeindre_verb"]]},{"speaker":"Tom","fr":"Le chat à la fenêtre contemple le ciel. L'autre se confine dans le carré de soleil.","en":"The cat at the window looks at the sky. The other one keeps to the square of sunlight.","spans":[[21,30,"fr_contempler_verb"],[51,58,"fr_confiner_verb"]]},{"speaker":"Papi Henri","fr":"Le castor encastre le rondin dans le mur. Ça tient.","en":"The beaver fits the log into the wall. It holds.","spans":[[10,18,"fr_encastrer_verb"]]}]},{"id":"C_ST_existence_seg013","title":"La nouvelle cuisine","premise":"A kitchen fitter installs a new kitchen for a customer.","cefr":"C2","lines":[{"speaker":"l'installateur","fr":"Le four est encastré dans le meuble, comme vous vouliez.","en":"The oven is built into the unit, as you wanted.","spans":[[12,20,"fr_encastrer_verb"]]},{"speaker":"Mme Bonnet","fr":"Parfait ! Et le lave-vaisselle ?","en":"Perfect! And the dishwasher?","spans":[]},{"speaker":"l'installateur","fr":"Il cadre parfaitement avec l'espace. Tout s'emboîte.","en":"It fits the space perfectly. Everything slots together.","spans":[[3,8,"fr_cadrer_verb"],[44,51,"fr_emboiter_verb"]]},{"speaker":"Mme Bonnet","fr":"Ce placard renferme quoi ?","en":"What's inside this cupboard?","spans":[]},{"speaker":"l'installateur","fr":"Les tuyaux. Ne le fermez pas complètement.","en":"The pipes. Don't close it completely.","spans":[]},{"speaker":"Mme Bonnet","fr":"Le résultat me subjugue ! C'est magnifique.","en":"I'm blown away by the result! It's gorgeous.","spans":[]},{"speaker":"l'installateur","fr":"Merci ! Si quelque chose ne va pas, vous pouvez récuser la facture.","en":"Thank you! If anything's wrong, you can dispute the bill.","spans":[]},{"speaker":"Mme Bonnet","fr":"Non, tout est parfait !","en":"No, everything's perfect!","spans":[]}]}],"sens/trouble":[{"id":"C_ST_existence_seg003","title":"Le secret du chef","premise":"A young cook asks an older chef about a family recipe.","cefr":"A2","lines":[{"speaker":"Samuel","fr":"Chef, votre sauce est incroyable. Vous me confiez la recette ?","en":"Chef, your sauce is incredible. Will you trust me with the recipe?","spans":[]},{"speaker":"le chef","fr":"Ha ha ! Elle vaut de l'or, cette recette.","en":"Ha ha! That recipe is worth its weight in gold.","spans":[]},{"speaker":"Samuel","fr":"Je promets de garder le secret.","en":"I promise to keep it secret.","spans":[]},{"speaker":"le chef","fr":"Bon. Il ne faut pas compliquer les choses : du beurre, des échalotes, du vin blanc.","en":"All right. You mustn't overcomplicate things: butter, shallots, white wine.","spans":[[20,30,"fr_compliquer_verb"]]},{"speaker":"Samuel","fr":"C'est tout ? Il manque quelque chose, non ?","en":"That's all? Something's missing, isn't it?","spans":[[16,22,"fr_manquer_verb"]]},{"speaker":"le chef","fr":"Le secret, c'est de maintenir le feu très doux pendant une heure.","en":"The secret is keeping the heat very low for an hour.","spans":[]},{"speaker":"Samuel","fr":"Mon ancien chef prétendait qu'il fallait de la crème !","en":"My old chef claimed you needed cream!","spans":[[16,26,"fr_pretendre_verb"]]},{"speaker":"le chef","fr":"Il avait tort !","en":"He was wrong!","spans":[]}]},{"id":"V_sens_trouble_01","title":"Petits ennuis","premise":"Tom and Léa sort out the small troubles in the room, gently.","cefr":"B1","lines":[{"speaker":"Tom","fr":"Le chaton complique toute la laine.","en":"The kitten complicates all the yarn.","spans":[[10,19,"fr_compliquer_verb"]]},{"speaker":"Léa","fr":"Le singe manque la banane. Elle passe trop haut.","en":"The monkey misses the banana. It goes by too high.","spans":[[9,15,"fr_manquer_verb"]]},{"speaker":"Maman","fr":"Le monsieur égare ses affaires dans le tas de vêtements.","en":"The man misplaces his things in the pile of clothes.","spans":[[12,17,"fr_egarer_verb"]]},{"speaker":"Léa","fr":"On ne néglige pas la plante, même si elle penche là-haut.","en":"We don't neglect the plant, even if it droops up there.","spans":[[6,13,"fr_negliger_verb"]]},{"speaker":"Tom","fr":"Le garçon prétend que la coupe est à lui.","en":"The boy claims that the trophy is his.","spans":[[10,17,"fr_pretendre_verb"]]},{"speaker":"Maman","fr":"Le cygne indigne le canard. Le détective présume que le chien veut la tarte.","en":"The swan fills the duck with indignation. The detective presumes the dog wants the pie.","spans":[[9,16,"fr_indigner_verb"],[41,48,"fr_presumer_verb"]]},{"speaker":"Léa","fr":"Un seul gland suffit pour endetter l'écureuil. La vache, elle, se contente d'un peu de beurre.","en":"One acorn is enough to get the squirrel into debt. The cow, though, is content with a little butter.","spans":[[26,34,"fr_endetter_verb"],[66,74,"fr_contenter_verb"]]}]},{"id":"C_ST_existence_seg008","title":"Le dîner improvisé","premise":"Friends arrive early for dinner and the host improvises.","cefr":"B2","lines":[{"speaker":"Clémence","fr":"Vous êtes déjà là ? J'ai présumé que vous arriviez à vingt heures !","en":"You're here already? I assumed you were arriving at eight!","spans":[[22,32,"fr_presumer_verb"]]},{"speaker":"Thomas","fr":"Pardon ! Le train avait de l'avance.","en":"Sorry! The train was early.","spans":[]},{"speaker":"Clémence","fr":"Pas de problème. Patientez un peu, je vais improviser un encas.","en":"No problem. Wait a little, I'll whip up some nibbles.","spans":[]},{"speaker":"Thomas","fr":"Merci. Et Paul ? Il s'est égaré en route ?","en":"Thanks. And Paul? Did he get lost on the way?","spans":[[26,31,"fr_egarer_verb"]]},{"speaker":"Clémence","fr":"Oui, il a encore égaré son téléphone !","en":"Yes, he's misplaced his phone again!","spans":[[17,22,"fr_egarer_verb"]]},{"speaker":"Thomas","fr":"Ha ha ! Et toi et ta sœur, vous vous êtes réconciliées ?","en":"Ha ha! And have you and your sister made up?","spans":[]},{"speaker":"Clémence","fr":"Oui, enfin. Elle s'est indignée pour rien.","en":"Yes, at last. She got outraged over nothing.","spans":[]},{"speaker":"Thomas","fr":"Tant mieux.","en":"Good.","spans":[]}]}],"sens/place":[{"id":"C_ST_existence_seg009","title":"La nouvelle bibliothèque","premise":"Two residents attend the opening of a new library in an old building.","cefr":"B2","lines":[{"speaker":"M. Joly","fr":"Le maire inaugure la bibliothèque aujourd'hui.","en":"The mayor is opening the library today.","spans":[[9,17,"fr_inaugurer_verb"]]},{"speaker":"Mme Faure","fr":"Enfin ! Ce vieux bâtiment était négligé depuis des années.","en":"At last! This old building had been neglected for years.","spans":[]},{"speaker":"M. Joly","fr":"Oui. Maintenant, la ville va l'entretenir.","en":"Yes. Now the town will look after it.","spans":[]},{"speaker":"Mme Faure","fr":"Il incarne l'histoire de notre quartier.","en":"It embodies the history of our neighborhood.","spans":[[3,10,"fr_incarner_verb"]]},{"speaker":"M. Joly","fr":"Ils ont aboli les frais d'inscription : c'est gratuit !","en":"They've abolished the registration fee: it's free!","spans":[[4,13,"fr_abolir_verb"]]},{"speaker":"Mme Faure","fr":"Super. Le brouillard s'est dissipé, il fait beau pour la fête.","en":"Great. The fog has lifted, it's nice weather for the party.","spans":[]},{"speaker":"M. Joly","fr":"On entre ?","en":"Should we go in?","spans":[]},{"speaker":"Mme Faure","fr":"Oui !","en":"Yes!","spans":[]}]},{"id":"V_sens_place_01","title":"Sur la place","premise":"Papi Henri and the children watch the public scenes play out.","cefr":"B2","lines":[{"speaker":"Léa","fr":"L'oie inaugure le petit pont : elle coupe le ruban.","en":"The goose inaugurates the little bridge: she cuts the ribbon.","spans":[[6,14,"fr_inaugurer_verb"]]},{"speaker":"Papi Henri","fr":"Les hiboux réconcilient le chiot avec le calme. Le livre et la balançoire concilient le travail et le jeu.","en":"The owls reconcile the puppy with the quiet. The book and the swing reconcile work and play.","spans":[[11,23,"fr_reconcilier_verb"],[74,84,"fr_concilier_verb"]]},{"speaker":"Tom","fr":"Les fourmis assiègent le sucrier. Et la cigogne rapatrie le petit avion vers le nid.","en":"The ants besiege the sugar bowl. And the stork sends the little plane home to the nest.","spans":[[12,21,"fr_assieger_verb"],[48,56,"fr_rapatrier_verb"]]},{"speaker":"Léa","fr":"Le roi abolit la pile de papiers : il les jette par la fenêtre.","en":"The king abolishes the pile of papers: he throws them out the window.","spans":[[7,13,"fr_abolir_verb"]]},{"speaker":"Tom","fr":"L'agent lègue sa montre à la fille. Le pâtissier adonne toute son attention aux beignets.","en":"The officer hands his watch down to the girl. The baker devotes all his attention to the doughnuts.","spans":[[8,13,"fr_leguer_verb"],[49,55,"fr_adonner_verb"]]},{"speaker":"Papi Henri","fr":"L'archéologue date le vieux vase. Le canard improvise avec l'arrosoir, et le garçon aux lunettes incarne un musicien.","en":"The archaeologist dates the old vase. The duck improvises with the watering can, and the boy in goggles embodies a musician.","spans":[[14,18,"fr_dater_verb"],[44,53,"fr_improviser_verb"],[97,104,"fr_incarner_verb"]]}]}],"sens/traces":[{"id":"V_sens_traces_01","title":"Les indices","premise":"Tom plays detective with Mom and Léa among the clues.","cefr":"B1","lines":[{"speaker":"Tom","fr":"Le hibou inspecte la salle avec sa loupe.","en":"The owl inspects the room with its magnifying glass.","spans":[[9,17,"fr_inspecter_verb"]]},{"speaker":"Léa","fr":"La souris expérimente le fromage et la pompe.","en":"The mouse experiments with the cheese and the pump.","spans":[[10,21,"fr_experimenter_verb"]]},{"speaker":"Maman","fr":"Ce chien détecte quelque chose dans le sac. L'autre empreint sa patte dans le plâtre.","en":"This dog detects something in the bag. The other one imprints its paw in the plaster.","spans":[[9,16,"fr_detecter_verb"],[52,60,"fr_empreindre_verb"]]},{"speaker":"Tom","fr":"Le perroquet atteste depuis la fenêtre. Il a tout vu.","en":"The parrot attests from the window. It saw everything.","spans":[[13,20,"fr_attester_verb"]]},{"speaker":"Léa","fr":"La petite souris souscrit à un gros fromage. Et la fille étoile le plafond.","en":"The little mouse subscribes to a big piece of cheese. And the girl stars the ceiling.","spans":[[17,25,"fr_souscrire_verb"],[57,63,"fr_etoiler_verb"]]},{"speaker":"Maman","fr":"Le paon flirte, la queue toute ouverte.","en":"The peacock flirts, tail wide open.","spans":[[8,14,"fr_flirter_verb"]]}]},{"id":"C_ST_perception_seg011","title":"L'atelier de science","premise":"A teacher runs a science workshop with a student.","cefr":"C1","lines":[{"speaker":"la professeure","fr":"Aujourd'hui, on va expérimenter avec des aimants.","en":"Today we're going to experiment with magnets.","spans":[[19,31,"fr_experimenter_verb"]]},{"speaker":"Noé","fr":"Super !","en":"Great!","spans":[]},{"speaker":"la professeure","fr":"Éparpille ces petits morceaux de fer sur la feuille.","en":"Scatter these little bits of iron on the sheet.","spans":[]},{"speaker":"Noé","fr":"Voilà.","en":"There.","spans":[]},{"speaker":"la professeure","fr":"Approche l'aimant. Tu vois ? Il détecte le métal.","en":"Bring the magnet closer. See? It detects the metal.","spans":[[32,39,"fr_detecter_verb"]]},{"speaker":"Noé","fr":"Le fer se disperse en lignes !","en":"The iron's spreading out in lines!","spans":[]},{"speaker":"la professeure","fr":"Bravo. Inspecte bien les lignes avec la loupe.","en":"Well done. Inspect the lines carefully with the magnifying glass.","spans":[[7,15,"fr_inspecter_verb"]]},{"speaker":"Noé","fr":"C'est trop beau !","en":"That's so cool!","spans":[]}]},{"id":"C_ST_perception_seg012","title":"Le nouvel abonnement","premise":"A woman tells her friend about her gym membership and a man she met there.","cefr":"C2","lines":[{"speaker":"Clémence","fr":"J'ai souscrit un abonnement à la salle de sport.","en":"I've taken out a gym membership.","spans":[[2,13,"fr_souscrire_verb"]]},{"speaker":"Julie","fr":"Toi ? Tu détestes le sport !","en":"You? You hate sport!","spans":[]},{"speaker":"Clémence","fr":"Le prof est très sympa... Il flirte un peu avec moi !","en":"The instructor's really nice... He flirts with me a bit!","spans":[[29,35,"fr_flirter_verb"]]},{"speaker":"Julie","fr":"Ha ha ! Je peux attester que tu rougis !","en":"Ha ha! I can vouch that you're blushing!","spans":[[16,24,"fr_attester_verb"]]},{"speaker":"Clémence","fr":"Arrête !","en":"Stop it!","spans":[]},{"speaker":"Julie","fr":"Ta voix est empreinte de bonheur.","en":"Your voice is full of happiness.","spans":[]},{"speaker":"Clémence","fr":"Ce soir, on dîne sous un ciel étoilé, dans son jardin.","en":"Tonight we're having dinner under a starry sky in his garden.","spans":[[30,36,"fr_etoiler_verb"]]},{"speaker":"Julie","fr":"Romantique !","en":"Romantic!","spans":[]}]}],"sens/teintes":[{"id":"V_sens_teintes_01","title":"Couleurs et petits bobos","premise":"Léa and Tom look at color, a dizzy duck, and a small scrape.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Le chat noir contraste avec la neige.","en":"The black cat contrasts with the snow.","spans":[[13,22,"fr_contraster_verb"]]},{"speaker":"Tom","fr":"Le peintre teinte le mouton en vert. Le mouton n'est pas convaincu.","en":"The painter tints the sheep green. The sheep is not convinced.","spans":[[11,17,"fr_teinter_verb"]]},{"speaker":"Maman","fr":"Le manège désoriente le canard. Il ne sait plus où aller.","en":"The carousel disorients the duck. It no longer knows where to go.","spans":[[10,20,"fr_desorienter_verb"]]},{"speaker":"Léa","fr":"Le chiot écorche son genou sur le filet. Le chat infirmier attend, avec sa trousse.","en":"The puppy grazes its knee on the net. The nurse cat waits, with its bag.","spans":[[9,16,"fr_ecorcher_verb"]]},{"speaker":"Tom","fr":"Le raton laveur dépouille le panier de ses pommes.","en":"The raccoon strips the basket of its apples.","spans":[[16,25,"fr_depouiller_verb"]]}]},{"id":"C_ST_perception_seg013","title":"Le tableau de la grand-mère","premise":"Two siblings look at a painting their grandmother made.","cefr":"C1","lines":[{"speaker":"Élodie","fr":"Mamie dépeint toujours la mer dans ses tableaux.","en":"Grandma always paints the sea in her pictures.","spans":[]},{"speaker":"Benoît","fr":"Les couleurs contrastent bien : le bleu et l'orange.","en":"The colors contrast well: blue and orange.","spans":[[13,24,"fr_contraster_verb"]]},{"speaker":"Élodie","fr":"Elle a teinté le ciel en rose.","en":"She's tinted the sky pink.","spans":[[5,13,"fr_teinter_verb"]]},{"speaker":"Benoît","fr":"Le chemin du tableau me désoriente un peu. Il mène où ?","en":"The path in the picture confuses me a bit. Where does it go?","spans":[[24,34,"fr_desorienter_verb"]]},{"speaker":"Élodie","fr":"À sa maison d'enfance.","en":"To her childhood home.","spans":[]},{"speaker":"Benoît","fr":"Attention, tu t'es écorché la main sur le cadre.","en":"Careful, you've scratched your hand on the frame.","spans":[[19,26,"fr_ecorcher_verb"]]},{"speaker":"Élodie","fr":"Ce n'est rien.","en":"It's nothing.","spans":[]},{"speaker":"Benoît","fr":"On l'accroche au salon ?","en":"Should we hang it in the living room?","spans":[]}]}],"sens/jardin":[{"id":"C_R_adj_senses_02","title":"Le week-end à la campagne","premise":"Two friends describe their weekend at a guest house in the countryside.","cefr":"A2","lines":[{"speaker":"Margot","fr":"Alors, ce week-end à la campagne ?","en":"So, how was the weekend in the country?","spans":[]},{"speaker":"Lucas","fr":"Très agréable ! La maison d'hôtes est dans un endroit tranquille, au milieu des vignes.","en":"Very nice! The guest house is in a quiet spot, in the middle of the vineyards.","spans":[[54,64,"fr_tranquille_adj"]]},{"speaker":"Margot","fr":"Et la cuisine ?","en":"And the food?","spans":[]},{"speaker":"Lucas","fr":"Un véritable bonheur. Tout est naturel, les légumes viennent du jardin.","en":"A real delight. Everything's natural, the vegetables come from the garden.","spans":[[31,38,"fr_naturel_adj"]]},{"speaker":"Margot","fr":"Tu as fait quoi ?","en":"What did you do?","spans":[]},{"speaker":"Lucas","fr":"Une randonnée. Je suis quelqu'un d'actif, je ne reste pas assis !","en":"A hike. I'm an active person, I don't sit still!","spans":[]},{"speaker":"Margot","fr":"Et ta copine ?","en":"And your girlfriend?","spans":[]},{"speaker":"Lucas","fr":"Elle a la peau sensible, elle est restée à l'ombre pour lire.","en":"She has sensitive skin, she stayed in the shade to read.","spans":[]},{"speaker":"Margot","fr":"Ce genre de moment, c'est précieux.","en":"Moments like that are precious.","spans":[]},{"speaker":"Lucas","fr":"Oui, c'était un week-end spécial. On a fêté nos deux ans !","en":"Yes, it was a special weekend. We celebrated two years together!","spans":[]}]}],"sens/matieres":[{"id":"C_R_adj_senses_03","title":"Le nouveau prof de maths","premise":"Two high-school students talk about their strict new math teacher.","cefr":"B2","lines":[{"speaker":"Noé","fr":"Le nouveau prof de maths est vraiment sévère !","en":"The new math teacher is really strict!","spans":[]},{"speaker":"Jade","fr":"Oui, il a une voix aiguë et un regard rude.","en":"Yes, he's got a high-pitched voice and a harsh look.","spans":[]},{"speaker":"Noé","fr":"Et il se tient toujours très raide, comme un soldat.","en":"And he always stands really stiffly, like a soldier.","spans":[[29,34,"fr_raide_adj"]]},{"speaker":"Jade","fr":"Ses cours sont pénibles. Trois heures de géométrie !","en":"His lessons are tiresome. Three hours of geometry!","spans":[]},{"speaker":"Noé","fr":"Mais il est civil, il ne crie jamais.","en":"But he's polite, he never shouts.","spans":[]},{"speaker":"Jade","fr":"C'est vrai. Il a dit qu'il était militaire avant ? J'ai un vague souvenir.","en":"That's true. Did he say he was in the army before? I vaguely remember something.","spans":[]},{"speaker":"Noé","fr":"Non, il était ingénieur. Il vient de la vie civile.","en":"No, he was an engineer. He comes from civilian life.","spans":[]},{"speaker":"Jade","fr":"Et tu as vu son crâne ? Lisse comme un œuf !","en":"And have you seen his head? Smooth as an egg!","spans":[[24,29,"fr_lisse_adj"]]},{"speaker":"Noé","fr":"Chut, il arrive !","en":"Shh, he's coming!","spans":[]}]}],"sens/sons":[{"id":"C_R_adj_senses_05","title":"Le téléphone de Papi","premise":"A woman calls her hard-of-hearing grandfather on the phone.","cefr":"B2","lines":[{"speaker":"Léa","fr":"Allô, Papi ? C'est Léa !","en":"Hello, Grandpa? It's Léa!","spans":[]},{"speaker":"Papi","fr":"Quoi ? Parle plus fort, je suis un peu sourd !","en":"What? Speak up, I'm a bit deaf!","spans":[[39,44,"fr_sourd_adj"]]},{"speaker":"Léa","fr":"C'est Léa ! Tu es assis ? J'ai une grande nouvelle.","en":"It's Léa! Are you sitting down? I've got big news.","spans":[]},{"speaker":"Papi","fr":"Oui, je suis dans mon fauteuil. Qu'est-ce qui se passe ?","en":"Yes, I'm in my armchair. What's going on?","spans":[]},{"speaker":"Léa","fr":"Je suis enceinte !","en":"I'm pregnant!","spans":[]},{"speaker":"Papi","fr":"Oh ! Ma voix est toute tremblante, ma chérie... C'est merveilleux !","en":"Oh! My voice is all shaky, darling... That's wonderful!","spans":[]},{"speaker":"Léa","fr":"Je sais que la ligne téléphonique est mauvaise, mais je voulais te le dire directement.","en":"I know the phone line is bad, but I wanted to tell you myself.","spans":[]},{"speaker":"Papi","fr":"Tu es consciente du bonheur que tu me donnes ?","en":"Do you realize how happy you've made me?","spans":[]},{"speaker":"Léa","fr":"Oui, Papi ! Et j'ai les mains glacées, tellement je suis émue.","en":"Yes, Grandpa! And my hands are icy, I'm so emotional.","spans":[]},{"speaker":"Papi","fr":"C'est cool, comme disent les jeunes !","en":"It's cool, as the young people say!","spans":[]},{"speaker":"Léa","fr":"Ha ha ! Ton rire est toujours aussi sonore !","en":"Ha ha! Your laugh is as loud as ever!","spans":[[36,42,"fr_sonore_adj"]]}]},{"id":"C_R_abs_senses_03","title":"Le voisin bruyant","premise":"A tenant complains to the building manager about noise from upstairs.","cefr":"C1","lines":[{"speaker":"Mme Morel","fr":"Bonjour. Je viens me plaindre du voisin du dessus. Il fait un tapage terrible !","en":"Hello. I've come to complain about the neighbor upstairs. He makes a terrible racket!","spans":[[62,68,"fr_tapage_noun"]]},{"speaker":"le gardien","fr":"Quel genre de bruit ?","en":"What kind of noise?","spans":[]},{"speaker":"Mme Morel","fr":"Des claquements de portes, des grincements de meubles à minuit...","en":"Doors banging, furniture creaking at midnight...","spans":[[4,15,"fr_claquement_noun"],[31,42,"fr_grincement_noun"]]},{"speaker":"le gardien","fr":"Je comprends. Je vais lui parler.","en":"I see. I'll talk to him.","spans":[]},{"speaker":"Mme Morel","fr":"Même ses chuchotements au téléphone traversent le plafond !","en":"Even his whispering on the phone comes through the ceiling!","spans":[[9,22,"fr_chuchotement_noun"]]},{"speaker":"le gardien","fr":"Les murs sont fins, ici. C'est une question de perception aussi.","en":"The walls are thin here. It's also a matter of perception.","spans":[]},{"speaker":"Mme Morel","fr":"Et hier, il jouait avec un pointeur laser, la lumière rouge entrait dans ma chambre !","en":"And yesterday he was playing with a laser pointer, the red light came into my bedroom!","spans":[]},{"speaker":"le gardien","fr":"D'accord, je lui parle aujourd'hui, avec subtilité.","en":"OK, I'll talk to him today, tactfully.","spans":[]},{"speaker":"Mme Morel","fr":"Merci. L'éloignement de la ville, c'était pour le calme !","en":"Thank you. I moved away from the city for the peace and quiet!","spans":[]},{"speaker":"le gardien","fr":"Je vous comprends, madame.","en":"I understand, madam.","spans":[]}]}],"sens/mysteres":[{"id":"C_R_adj_senses_07","title":"La soirée au musée","premise":"A couple visit a museum at night and look at a dramatic painting.","cefr":"C1","lines":[{"speaker":"Élise","fr":"Regarde ce tableau : la lune argentée au-dessus de la mer.","en":"Look at this painting: the silvery moon above the sea.","spans":[]},{"speaker":"Raphaël","fr":"Et ce personnage hautain, au premier plan. Il regarde tout le monde de haut !","en":"And that haughty figure in the foreground. He looks down on everyone!","spans":[]},{"speaker":"Élise","fr":"Il a un visage osseux, des jambes grêles... Il n'a pas l'air en forme !","en":"He's got a bony face, spindly legs... He doesn't look healthy!","spans":[]},{"speaker":"Raphaël","fr":"Ha ha ! Et derrière lui, une falaise vertigineuse.","en":"Ha ha! And behind him, a dizzying cliff.","spans":[[37,49,"fr_vertigineux_adj"]]},{"speaker":"Élise","fr":"Tu vois l'ombre furtive dans le coin ?","en":"Can you see the furtive shadow in the corner?","spans":[[16,23,"fr_furtif_adj"]]},{"speaker":"Raphaël","fr":"Un voleur, peut-être !","en":"A thief, maybe!","spans":[]},{"speaker":"Élise","fr":"Ce peintre a eu une triple vie : peintre, poète et marin.","en":"This painter had a triple life: painter, poet and sailor.","spans":[]},{"speaker":"Raphaël","fr":"Impressionnant. On va boire un verre ? J'ai les mains collantes après ce bonbon.","en":"Impressive. Should we go for a drink? My hands are sticky after that candy.","spans":[]},{"speaker":"Élise","fr":"D'accord, allons-y !","en":"OK, let's go!","spans":[]}]},{"id":"C_R_adj_senses_09","title":"La soirée film d'horreur","premise":"Two teenagers choose a movie to watch on a rainy evening.","cefr":"C1","lines":[{"speaker":"Nina","fr":"Il pleut, le ciel est morne... On regarde un film ?","en":"It's raining, the sky is gloomy... Should we watch a movie?","spans":[[22,27,"fr_morne_adj"]]},{"speaker":"Malik","fr":"Oui ! Un film d'horreur gothique, avec un château et des fantômes !","en":"Yes! A gothic horror movie, with a castle and ghosts!","spans":[[24,32,"fr_gothique_adj"]]},{"speaker":"Nina","fr":"Pas trop effrayant, hein. Je n'aime pas le surnaturel.","en":"Not too scary, OK? I don't like the supernatural.","spans":[[43,53,"fr_surnaturel_adj"]]},{"speaker":"Malik","fr":"Tu n'es pas très hardie !","en":"You're not very daring!","spans":[]},{"speaker":"Nina","fr":"Si ! Mais je préfère les films mélancoliques, avec de la belle musique.","en":"I am! But I prefer melancholy movies, with beautiful music.","spans":[[31,44,"fr_melancolique_adj"]]},{"speaker":"Malik","fr":"Alors celui-ci : l'image est un peu floue, c'est un vieux film.","en":"Then this one: the picture's a bit blurry, it's an old movie.","spans":[]},{"speaker":"Nina","fr":"Et l'affiche, avec ces couleurs criardes ?","en":"And the poster, with those garish colors?","spans":[]},{"speaker":"Malik","fr":"C'est un film des années soixante-dix !","en":"It's a seventies movie!","spans":[]},{"speaker":"Nina","fr":"Bon, d'accord. Avec du pop-corn !","en":"OK, fine. With popcorn!","spans":[]},{"speaker":"Malik","fr":"Je le prépare.","en":"I'll make it.","spans":[]}]}],"sens/labo":[{"id":"C_R_adj_senses_08","title":"La réunion du conseil","premise":"Two members of an advisory council discuss a new playground project.","cefr":"C1","lines":[{"speaker":"Mme Duval","fr":"Le conseil consultatif a voté pour le nouveau parc. C'était unanime !","en":"The advisory council voted for the new park. It was unanimous!","spans":[]},{"speaker":"M. Kone","fr":"Excellente nouvelle. Le sol sera en caoutchouc, pas glissant ?","en":"Excellent news. Will the ground be rubber, not slippery?","spans":[]},{"speaker":"Mme Duval","fr":"Oui, en matière synthétique, très fonctionnelle.","en":"Yes, synthetic material, very practical.","spans":[[16,27,"fr_synthetique_adj"],[34,47,"fr_fonctionnel_adj"]]},{"speaker":"M. Kone","fr":"Et les arbres ? Certains enfants sont allergiques au pollen.","en":"And the trees? Some children are allergic to pollen.","spans":[]},{"speaker":"Mme Duval","fr":"On a choisi des arbres sans pollen.","en":"We've chosen pollen-free trees.","spans":[]},{"speaker":"M. Kone","fr":"Parfait. Et l'éclairage le soir ?","en":"Perfect. And the lighting in the evening?","spans":[]},{"speaker":"Mme Duval","fr":"Une lumière diffuse, douce, pour ne pas gêner les voisins.","en":"Soft, diffuse lighting, so as not to disturb the neighbors.","spans":[[12,19,"fr_diffus_adj"]]},{"speaker":"M. Kone","fr":"Et l'aire de jeux est complémentaire de celle de l'école ?","en":"And is the playground complementary to the school's?","spans":[]},{"speaker":"Mme Duval","fr":"Exactement, pour les plus petits.","en":"Exactly, for the little ones.","spans":[]},{"speaker":"M. Kone","fr":"Bravo, c'est un beau projet.","en":"Well done, it's a lovely project.","spans":[]}]}],"sens/sens":[{"id":"C_R_abs_senses_01","title":"La maison de vacances","premise":"A family arrives at their vacation house and discovers it.","cefr":"A2","lines":[{"speaker":"Louise","fr":"Maman, quelle vue ! On voit la mer depuis ma chambre !","en":"Mom, what a view! You can see the sea from my room!","spans":[[14,17,"fr_vue_noun"]]},{"speaker":"Maman","fr":"Magnifique. Et il y a beaucoup de lumière dans le salon.","en":"Wonderful. And there's lots of light in the living room.","spans":[[34,41,"fr_lumiere_noun"]]},{"speaker":"Louise","fr":"Tu sens cette odeur ? C'est le jasmin dans le jardin.","en":"Can you smell that? It's the jasmine in the garden.","spans":[[14,19,"fr_odeur_noun"]]},{"speaker":"Maman","fr":"Oui. Et écoute ce silence ! Pas de bruit de voitures.","en":"Yes. And listen to that silence! No traffic noise.","spans":[[18,25,"fr_silence_noun"],[35,40,"fr_bruit_noun"]]},{"speaker":"Louise","fr":"On mange dehors, à l'ombre du grand arbre ?","en":"Should we eat outside, in the shade of the big tree?","spans":[[21,26,"fr_ombre_noun"]]},{"speaker":"Maman","fr":"Bonne idée. Regarde Papa, il fait un geste depuis la plage.","en":"Good idea. Look at Dad, he's waving from the beach.","spans":[[37,42,"fr_geste_noun"]]},{"speaker":"Louise","fr":"Il nous appelle ! On y va ?","en":"He's calling us! Should we go?","spans":[]},{"speaker":"Maman","fr":"D'accord. Mais d'abord, la crème solaire !","en":"OK. But suncream first!","spans":[]},{"speaker":"Louise","fr":"Maman, tu as un regard sévère, là !","en":"Mom, you've got a stern look on your face!","spans":[[16,22,"fr_regard_noun"]]},{"speaker":"Maman","fr":"Ha ha ! Parce que c'est important !","en":"Ha ha! Because it matters!","spans":[]}]}],"sens/lumieres":[{"id":"C_R_abs_senses_02","title":"La panne dans le grenier","premise":"Two siblings explore their grandparents' dark attic during a power cut.","cefr":"B1","lines":[{"speaker":"Lisa","fr":"Il fait noir ! Je ne vois rien dans cette obscurité.","en":"It's dark! I can't see anything in this darkness.","spans":[[42,51,"fr_obscurite_noun"]]},{"speaker":"Tom","fr":"Attends, j'allume la lampe de mon téléphone. Appuie sur la touche, là.","en":"Wait, I'll turn on my phone flashlight. Press that button there.","spans":[]},{"speaker":"Lisa","fr":"Voilà une petite lueur. Mais quel éclairage faible !","en":"There's a little glimmer. But what weak lighting!","spans":[[17,22,"fr_lueur_noun"],[34,43,"fr_eclairage_noun"]]},{"speaker":"Tom","fr":"Regarde, une silhouette au fond !","en":"Look, a figure at the back!","spans":[]},{"speaker":"Lisa","fr":"Ah ! Ah non, c'est un vieux manteau sur un cintre.","en":"Ah! Oh no, it's an old coat on a hanger.","spans":[]},{"speaker":"Tom","fr":"J'ai une drôle de sensation. Comme si quelqu'un nous regardait.","en":"I've got a funny feeling. As if someone was watching us.","spans":[]},{"speaker":"Lisa","fr":"Mon instinct me dit de redescendre !","en":"My instinct tells me to go back down!","spans":[]},{"speaker":"Tom","fr":"Beurk, une toile d'araignée sur ma main !","en":"Yuck, a cobweb on my hand!","spans":[]},{"speaker":"Lisa","fr":"Ha ha ! Ton visage plein de dégoût !","en":"Ha ha! The disgust on your face!","spans":[]},{"speaker":"Tom","fr":"Allez, on redescend.","en":"Come on, let's go down.","spans":[]}]}]};
